async function renderRoute() {
  state.route = parseRoute(); renderNavigation(); closeMobileNav(); main.innerHTML = '<div class="page-loading" aria-label="Loading"><span></span><span></span><span></span></div>'; main.focus({ preventScroll: true });
  try { const renderers = { overview: renderOverview, employees: renderEmployees, groups: renderGroups, categories: renderCategories, policies: renderPolicies, rules: renderRules, overrides: renderOverrides, reconciliation: renderReconciliation, audit: renderAudit, settings: renderSettings }; await renderers[state.route](); hydrateIcons(main); } catch (error) { renderError(error); }
}
function openMobileNav() { document.body.classList.add('sidebar-open'); }
function closeMobileNav() { document.body.classList.remove('sidebar-open'); }
function commandItems() {
  return [...navGroups.flatMap((group) => group.items.map(([route, label, glyph]) => ({ label, detail: group.label || 'Workspace', glyph, route }))), { label: 'Add employee', detail: 'Action', glyph: 'plus', action: 'new-employee' }, { label: 'Create assignment rule', detail: 'Action', glyph: 'rules', action: 'new-rule' }, { label: 'Add manual override', detail: 'Action', glyph: 'override', action: 'new-override' }, { label: 'Reconcile workspace', detail: 'Action', glyph: 'refresh', action: 'full-reconcile' }];
}
function renderCommands(query = '') {
  const items = commandItems().filter((item) => `${item.label} ${item.detail}`.toLowerCase().includes(query.toLowerCase()));
  $('#command-results').innerHTML = `<div class="command-group-label">Pages and actions</div>${items.map((item, index) => `<button class="command-item ${index === 0 ? 'selected' : ''}" role="option" data-route="${item.route || ''}" data-action="${item.action || ''}"><span>${icon(item.glyph)}</span><span><strong>${esc(item.label)}</strong><small>${esc(item.detail)}</small></span><kbd>↵</kbd></button>`).join('') || '<div class="empty-state compact"><div><p>No matching pages or actions.</p></div></div>'}`;
}
function openCommands() { renderCommands(); const dialog = $('#command-dialog'); dialog.showModal(); $('#command-input').value = ''; $('#command-input').focus(); }
async function handleSimpleForm(form) {
  const data = Object.fromEntries(new FormData(form)); const submit = form.dataset.submit; const button = $('button[type="submit"]', form); button.disabled = true;
  try {
    if ((submit === 'create-override' || submit === 'add-group-member') && !data.employeeId) { toast('Select an employee from the search results.', 'error'); button.disabled = false; return; }
    if (submit === 'create-group') await api('/groups', { method: 'POST', body: JSON.stringify({ key: data.key, name: data.name, description: data.description || null }) });
    else if (submit === 'edit-group') await api(`/groups/${data.groupId}`, { method: 'PATCH', body: JSON.stringify({ name: data.name, description: data.description || null }) });
    else if (submit === 'create-category') await api('/policy-categories', { method: 'POST', body: JSON.stringify({ key: data.key, name: data.name, cardinality: data.cardinality }) });
    else if (submit === 'edit-category') await api(`/policy-categories/${data.categoryId}`, { method: 'PATCH', body: JSON.stringify({ name: data.name }) });
    else if (submit === 'create-policy') await api('/policies', { method: 'POST', body: JSON.stringify({ key: data.key, categoryId: data.categoryId, name: data.name, description: data.description || null, enabled: true, effectiveFrom: data.effectiveFrom }) });
    else if (submit === 'edit-policy') await api(`/policies/${data.policyId}/versions`, { method: 'POST', body: JSON.stringify({ name: data.name, description: data.description || null, enabled: data.enabled === 'true', metadata: {}, effectiveFrom: data.effectiveFrom }) });
    else if (submit === 'create-override') await api('/manual-overrides', { method: 'POST', body: JSON.stringify({ employeeId: data.employeeId, policyId: data.policyId, action: data.action, priority: 0, reason: data.reason, validFrom: data.validFrom, validTo: data.validTo || null }) });
    else if (submit === 'add-group-member') await api(`/groups/${data.groupId}/members`, { method: 'POST', body: JSON.stringify({ employeeId: data.employeeId, effectiveFrom: today() }) });
    closeDialog('modal'); toast(submit === 'create-override' ? 'Manual override added and reconciliation queued.' : 'Saved successfully.'); await renderRoute();
  } catch (error) { toast(error.message, 'error'); button.disabled = false; }
}
async function actionHandler(action, element) {
  if (action === 'refresh') return renderRoute(); if (action === 'new-employee') return openEmployeeFlow(); if (action === 'edit-employee') { closeDialog('drawer'); return openEmployeeFlow(element.dataset.id); }
  if (action === 'employee-next') return employeeNext(); if (action === 'employee-back') { captureEmployeeStep(); state.employeeFlow.step -= 1; return renderEmployeeFlow(); }
  if (action === 'add-attribute') { captureEmployeeStep(); state.employeeFlow.values.attributes[`attribute_${Object.keys(state.employeeFlow.values.attributes).length + 1}`] = ''; return renderEmployeeFlow(); }
  if (action === 'explain') return explainAssignment(element.dataset.employeeId, element.dataset.assignmentId);
  if (action === 'new-group') return formDialog({ title: 'Create group', description: 'Groups define reusable employee populations for membership-aware rules.', submit: 'create-group', fields: '<label class="field"><span>Name</span><input name="name" required maxlength="300" /></label><label class="field"><span>Stable key</span><input name="key" required pattern="[A-Za-z0-9][A-Za-z0-9_.-]*" /></label><label class="field full"><span>Description</span><textarea name="description" maxlength="2000"></textarea></label>' });
  if (action === 'edit-group') { const group = await api(`/groups/${element.dataset.id}`); closeDialog('drawer'); return formDialog({ title: `Edit ${group.name}`, description: 'The stable group key and rule dependencies remain unchanged.', submit: 'edit-group', fields: `<input type="hidden" name="groupId" value="${attr(group.id)}"><label class="field full"><span>Name</span><input name="name" required maxlength="300" value="${attr(group.name)}" /></label><label class="field full"><span>Description</span><textarea name="description" maxlength="2000">${esc(group.description || '')}</textarea></label>` }); }
  if (action === 'new-category') return formDialog({ title: 'Create assignment category', description: 'Choose whether one policy wins or multiple compatible policies may coexist.', submit: 'create-category', fields: '<label class="field"><span>Name</span><input name="name" required /></label><label class="field"><span>Stable key</span><input name="key" required pattern="[A-Za-z0-9][A-Za-z0-9_.-]*" /></label><label class="field full"><span>Assignment behavior</span><select name="cardinality"><option value="SINGLE">One winning policy</option><option value="MULTIPLE">Multiple policies may coexist</option></select><small>This cannot be changed after creation.</small></label>' });
  if (action === 'edit-category') { const category = (await api('/policy-categories')).data.find((item) => item.id === element.dataset.id); closeDialog('drawer'); return formDialog({ title: `Rename ${category.name}`, description: 'Cardinality and the stable key remain immutable to preserve historical resolution.', submit: 'edit-category', fields: `<input type="hidden" name="categoryId" value="${attr(category.id)}"><label class="field full"><span>Name</span><input name="name" required maxlength="300" value="${attr(category.name)}" /></label>` }); }
  if (action === 'new-policy') {
    if (!state.refs.categories.length) state.refs.categories = (await api('/policy-categories')).data; if (!state.refs.categories.length) { toast('Create an assignment category first.', 'error'); navigate('categories'); return; }
    return formDialog({ title: 'Create policy', description: 'Policies are outcomes. Rules and overrides determine who receives them.', submit: 'create-policy', fields: `<label class="field"><span>Name</span><input name="name" required /></label><label class="field"><span>Stable key</span><input name="key" required pattern="[A-Za-z0-9][A-Za-z0-9_.-]*" /></label><label class="field full"><span>Category</span><select name="categoryId" required>${state.refs.categories.map((category) => `<option value="${attr(category.id)}">${esc(category.name)} · ${category.cardinality === 'SINGLE' ? 'one winner' : 'multiple'}</option>`).join('')}</select></label><label class="field full"><span>Description</span><textarea name="description"></textarea></label><label class="field"><span>Effective from</span><input name="effectiveFrom" type="date" value="${today()}" min="${today()}" required /></label>` });
  }
  if (action === 'edit-policy') { const result = await api('/policies'); const policy = result.data.find((item) => item.id === element.dataset.id); closeDialog('drawer'); return formDialog({ title: `Update ${policy.name}`, description: 'Publishing creates a new effective policy version and reconciles affected assignments.', submit: 'edit-policy', submitLabel: 'Publish version', fields: `<input type="hidden" name="policyId" value="${attr(policy.id)}"><label class="field"><span>Name</span><input name="name" required value="${attr(policy.name)}" /></label><label class="field"><span>Status</span><select name="enabled"><option value="true" ${policy.enabled ? 'selected' : ''}>Enabled</option><option value="false" ${policy.enabled ? '' : 'selected'}>Disabled</option></select></label><label class="field full"><span>Description</span><textarea name="description">${esc(policy.description || '')}</textarea></label><label class="field"><span>Effective from</span><input name="effectiveFrom" type="date" value="${today()}" min="${today()}" required /></label>` }); }
  if (action === 'new-rule') return openRuleFlow(); if (action === 'edit-rule') { const result = await api('/rules'); const rule = result.data.find((item) => item.id === element.dataset.id); closeDialog('drawer'); return openRuleFlow(rule); }
  if (['add-condition', 'add-group', 'add-not'].includes(action)) {
    captureRuleFlow(); const group = conditionAtPath(element.dataset.path || 'root');
    if (group.type !== 'and' && group.type !== 'or') return;
    if (action === 'add-condition') group.conditions.push(freshCondition());
    if (action === 'add-group') group.conditions.push({ type: 'and', conditions: [freshCondition()] });
    if (action === 'add-not') group.conditions.push({ type: 'not', condition: freshCondition() });
    return renderRuleFlow();
  }
  if (action === 'preview-rule') return previewRule(); if (action === 'publish-rule') return publishRule(); if (action === 'new-override') return openOverrideForm();
  if (action === 'revoke-override' && await confirmAction({ title: 'Revoke manual override?', message: `${element.dataset.policy} will return to automatic rule resolution. The historical override remains auditable.`, label: 'Revoke override' })) { await api(`/manual-overrides/${element.dataset.id}`, { method: 'DELETE' }); toast('Override revoked and reconciliation queued.'); return renderRoute(); }
  if (action === 'full-reconcile' && await confirmAction({ title: 'Reconcile the entire workspace?', message: 'This queues a retry-safe full reconciliation. Existing correct assignments remain untouched.', label: 'Queue reconciliation' })) { await api('/reconciliation/trigger', { method: 'POST', body: '{}' }); toast('Full reconciliation queued.'); return renderRoute(); }
  if (action === 'add-group-member') return formDialog({ title: 'Add group member', description: 'Membership changes queue dependency-aware reconciliation for this employee.', submit: 'add-group-member', submitLabel: 'Add member', fields: `<input type="hidden" name="groupId" value="${attr(element.dataset.groupId)}">${employeePicker()}` });
  if (action === 'select-employee') { const lookup = element.closest('.employee-lookup'); $('[name="employeeId"]', lookup).value = element.dataset.id; $('[data-employee-lookup]', lookup).value = element.dataset.name; $('.lookup-results', lookup).innerHTML = `<div class="member-row selected"><span class="cell-stack"><strong>${esc(element.dataset.name)}</strong><small>${esc(element.dataset.detail)}</small></span><span class="tag accent">Selected</span></div>`; return; }
  if (action === 'remove-group-member' && await confirmAction({ title: 'Remove group member?', message: `${element.dataset.name} may lose policies assigned by rules that depend on this group.`, label: 'Remove member' })) { await api(`/groups/${element.dataset.groupId}/members/${element.dataset.employeeId}?effectiveDate=${today()}`, { method: 'DELETE' }); toast('Membership removed and reconciliation queued.'); return openGroup(element.dataset.groupId); }
}

document.addEventListener('click', async (event) => {
  const element = event.target.closest('[data-route],[data-action],[data-close],[data-open],[data-page],[data-group-page],[data-sort],[data-employee-tab],[data-node-logic],[data-remove-node],[data-remove-attribute]'); if (!element) return;
  try {
    if (element.dataset.route) { closeDialog('command-dialog'); closeDialog('drawer'); navigate(element.dataset.route); return; } if (element.dataset.close) { closeDialog(element.dataset.close); return; }
    if (element.dataset.open === 'employee') { await openEmployee(element.dataset.id); return; } if (element.dataset.open === 'group') { await openGroup(element.dataset.id); return; } if (element.dataset.open === 'category') { await openCategory(element.dataset.id); return; } if (element.dataset.open === 'policy') { await openPolicy(element.dataset.id); return; } if (element.dataset.open === 'rule') { await openRule(element.dataset.id); return; }
    if (element.dataset.employeeTab) { await openEmployee(element.dataset.id, element.dataset.employeeTab); return; }
    if (element.dataset.page) { state.employeeQuery.offset = Math.max(0, state.employeeQuery.offset + (element.dataset.page === 'next' ? state.employeeQuery.limit : -state.employeeQuery.limit)); await renderEmployees(); return; }
    if (element.dataset.groupPage) { const offset = Math.max(0, Number(element.dataset.offset) + (element.dataset.groupPage === 'next' ? 100 : -100)); await openGroup(element.dataset.id, element.dataset.search, offset); return; }
    if (element.dataset.sort) { state.employeeQuery.direction = state.employeeQuery.sort === element.dataset.sort && state.employeeQuery.direction === 'asc' ? 'desc' : 'asc'; state.employeeQuery.sort = element.dataset.sort; state.employeeQuery.offset = 0; await renderEmployees(); return; }
    if (element.dataset.nodeLogic) { captureRuleFlow(); conditionAtPath(element.dataset.path).type = element.dataset.nodeLogic; renderRuleFlow(); return; }
    if (element.dataset.removeNode !== undefined) { captureRuleFlow(); removeConditionAtPath(element.dataset.removeNode); renderRuleFlow(); return; }
    if (element.dataset.removeAttribute !== undefined) { captureEmployeeStep(); const key = Object.keys(state.employeeFlow.values.attributes)[Number(element.dataset.removeAttribute)]; delete state.employeeFlow.values.attributes[key]; renderEmployeeFlow(); return; }
    if (element.dataset.action) await actionHandler(element.dataset.action, element);
  } catch (error) { toast(error.message, 'error'); }
});
document.addEventListener('submit', (event) => { if (event.target.id === 'simple-form' && event.target.dataset.submit !== 'create-company') { event.preventDefault(); void handleSimpleForm(event.target); } });
document.addEventListener('change', async (event) => {
  const filter = event.target.dataset.employeeFilter; if (filter) { state.employeeQuery[filter] = event.target.value; state.employeeQuery.offset = 0; await renderEmployees(); }
  if (event.target.matches('[data-rule-fact],[data-rule-operator],[data-rule-value],#rule-policy,#rule-enabled')) { captureRuleFlow(); renderRuleFlow(); }
  if (event.target.id === 'rule-status') filterRules();
});
let searchTimer;
document.addEventListener('input', (event) => {
  if (event.target.id === 'employee-search') { clearTimeout(searchTimer); searchTimer = window.setTimeout(async () => { state.employeeQuery.search = event.target.value; state.employeeQuery.offset = 0; await renderEmployees(); $('#employee-search')?.focus(); }, 260); }
  if (event.target.matches('[data-employee-lookup]')) { clearTimeout(searchTimer); searchTimer = window.setTimeout(() => void searchEmployeePicker(event.target), 250); }
  if (event.target.matches('[data-group-member-search]')) { clearTimeout(searchTimer); const input = event.target; searchTimer = window.setTimeout(() => void openGroup(input.dataset.groupMemberSearch, input.value, 0), 250); }
  if (event.target.id === 'command-input') renderCommands(event.target.value); if (event.target.id === 'rule-search') { clearTimeout(searchTimer); searchTimer = window.setTimeout(filterRules, 180); }
});
async function filterRules() {
  const result = await api('/rules'); const query = ($('#rule-search')?.value || '').toLowerCase(); const wanted = $('#rule-status')?.value || '';
  const latest = [...new Map(result.data.map((rule) => [rule.id, rule])).values()].filter((rule) => `${rule.key} ${rule.policy_name} ${conditionSummary(rule.condition)}`.toLowerCase().includes(query) && (!wanted || (wanted === 'DISABLED' ? !rule.enabled : rule.status === wanted))); $('#rules-table').innerHTML = renderRulesTable(latest); hydrateIcons($('#rules-table'));
}
document.addEventListener('keydown', (event) => {
  if ((event.metaKey || event.ctrlKey) && event.key.toLowerCase() === 'k') { event.preventDefault(); openCommands(); } if (event.key === 'Escape') closeMobileNav();
  if ($('#command-dialog').open && ['ArrowDown', 'ArrowUp'].includes(event.key)) { event.preventDefault(); const items = $$('.command-item'); const current = items.findIndex((item) => item.classList.contains('selected')); const next = event.key === 'ArrowDown' ? Math.min(items.length - 1, current + 1) : Math.max(0, current - 1); items.forEach((item, index) => item.classList.toggle('selected', index === next)); items[next]?.focus(); }
});

$('#command-trigger').addEventListener('click', openCommands); $('#refresh-view').innerHTML = icon('refresh'); $('#refresh-view').addEventListener('click', () => void renderRoute()); $('#sidebar-trigger').innerHTML = icon('menu'); $('#sidebar-trigger').addEventListener('click', openMobileNav); $('#sidebar-close').innerHTML = icon('close'); $('#sidebar-close').addEventListener('click', closeMobileNav); $('#sidebar-scrim').addEventListener('click', closeMobileNav);
$('#company').addEventListener('change', async (event) => { state.companyId = event.target.value; localStorage.setItem('policy-company', state.companyId); closeDialog('drawer'); await renderRoute(); }); window.addEventListener('hashchange', () => void renderRoute());
function populateCompanies() { $('#company').innerHTML = state.companies.map((company) => `<option value="${attr(company.id)}" ${company.id === state.companyId ? 'selected' : ''}>${esc(company.name)}</option>`).join(''); }
async function initialize() {
  hydrateIcons();
  try {
    const [companies, health] = await Promise.all([api('/companies'), api('/health')]); state.companies = companies.data;
    if (!state.companies.length) {
      formDialog({ title: 'Create your workspace', description: 'Start with a company boundary. All people, policies, rules, and decisions remain tenant-isolated.', submit: 'create-company', submitLabel: 'Create workspace', fields: '<label class="field full"><span>Company name</span><input name="name" required maxlength="300" autofocus /></label>' });
      const form = $('#simple-form'); form.addEventListener('submit', async (event) => { event.preventDefault(); const data = new FormData(form); try { const company = await api('/companies', { method: 'POST', body: JSON.stringify({ name: data.get('name') }) }); state.companies = [company]; state.companyId = company.id; localStorage.setItem('policy-company', company.id); closeDialog('modal'); populateCompanies(); await renderRoute(); } catch (error) { toast(error.message, 'error'); } });
    } else { if (!state.companies.some((company) => company.id === state.companyId)) state.companyId = state.companies[0].id; localStorage.setItem('policy-company', state.companyId); populateCompanies(); }
    $('#health-dot').classList.add(health.status === 'ok' ? 'healthy' : 'unhealthy'); $('#health-label').textContent = health.status === 'ok' ? 'System healthy' : 'System unavailable'; await renderRoute();
  } catch (error) { $('#health-dot').classList.add('unhealthy'); $('#health-label').textContent = 'Connection issue'; renderError(error); }
}
void initialize();
